from __future__ import annotations

# Phase V-B (phase5b) — corrected determinism revision.
#
# IMPORTANT INCOMPATIBILITY NOTE:
#   This revision replaces all experiment-affecting uses of Python's built-in
#   ``hash()`` with a stable, domain-separated SHA-256 helper (_stable_hash).
#   Python's built-in ``hash()`` is randomised per-process via PYTHONHASHSEED,
#   so historical Phase V (phase5a) results are NOT bitwise comparable to
#   results generated by this revision.  Do NOT compare or merge artifacts from
#   phase5a and phase5b without explicit reconciliation.
#
#   The three experiment pools — development, selection-validation, and
#   final-validation — now use demonstrably disjoint mechanism, pair, and
#   triple identifiers.  Final-validation remains locked and must not be
#   executed without an explicit --unlock-test flag.
