#: Experiment revision identifier.  Artifacts produced by this code carry
#: ``phase_variant = PHASE5_REVISION`` so they are not silently confused with
#: historical phase5a artifacts.
PHASE5_REVISION: str = "phase5b"


class Phase5Family(str, Enum):
    V1_UNSEEN_MECHANISM = "V1"
    V2_UNSEEN_PAIR = "V2"
    V3_THREE_FAULT = "V3"
    V4_UNKNOWN_FAULT = "V4"


class Phase5RelationType(str, Enum):
    STRICT_MASKING = "strict_masking"
    SOFT_MASKING = "soft_masking"
    INDEPENDENT = "independent"
    SYNERGISTIC = "synergistic"


class Phase5Intervention(str, Enum):
    rG = "rG"
    rB = "rB"
    rR = "rR"
    rW = "rW"
    rD = "rD"
    rJ = "rJ"
    r0 = "r0"
    stop = "stop"


class DependencyType(str, Enum):
    NONE = "none"
    CHAIN = "chain"
    FORK = "fork"
    PARTIAL_SUFFICIENCY = "partial_sufficiency"


def _stable_hash(domain: str, *args: object) -> int:
    """Return a stable, non-negative integer derived from *domain* and *args*.

    Uses SHA-256 with domain separation.  Each argument is encoded as a
    length-prefixed UTF-8 string so that different argument sequences cannot
    collide (e.g. ``("ab", "c")`` vs ``("a", "bc")``).  This helper is the
    **only** approved way to derive integer hashes for experiment selection
    in Phase V-B.  Do NOT use Python's built-in ``hash()``; it is randomised
    per-process via ``PYTHONHASHSEED`` and produces non-reproducible results.
    """
    payload = domain.encode("utf-8")
    for arg in args:
        encoded = str(arg).encode("utf-8")
        payload += len(encoded).to_bytes(4, "big") + encoded
    return int.from_bytes(hashlib.sha256(payload).digest()[:8], "big")


